}

public int[] searchForStartAndEndIndexOfAnElementInAnArray(int[] A, int B) {
    int N = A.length;
    int[] result = new int[]{-1, -1};
    if (N == 0) return result;

    int low = 0, high = N - 1, first = -1, last = -1;

    // First occurrence
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (A[mid] < B)      low  = mid + 1;
        else if (A[mid] > B) high = mid - 1;
        else { first = mid; high = mid - 1; }
    }

    // Last occurrence
    low = 0; high = N - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (A[mid] < B)      low  = mid + 1;
        else if (A[mid] > B) high = mid - 1;
        else { last = mid; low = mid + 1; }
    }

    if (first != -1) { result[0] = first; result[1] = last; }
    return result;
}

