public int singleElementInASortedArray(int[] A) {
    int N = A.length;
    if (N == 1)             return A[0];
    if (A[0] != A[1])       return A[0];
    if (A[N - 1] != A[N-2]) return A[N - 1];

    int low = 1, high = N - 2;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (A[mid] == A[mid + 1]) {
            if (mid % 2 == 0) low  = mid + 2;
            else              high = mid - 1;
        } else if (A[mid] == A[mid - 1]) {
            mid = mid - 1;
            if (mid % 2 == 0) low  = mid + 2;
            else              high = mid - 1;
        } else {
            return A[mid];
        }
    }
    return -1;
}

public int xorScan(int[] A) {
    int x = 0;
    for (int v : A) x ^= v;
    return x;
}

public int linearScan(int[] A) {
    int N = A.length;
    if (N == 1) return A[0];
    if (A[0] >= A[1]) return A[0];
    if (A[N-1] >= A[N-2]) return A[N-1];
    for (int i = 1; i < N - 1; i++) {
        if (A[i] >= A[i-1] && A[i] >= A[i+1]) return A[i];
    }
    return -1;
}

public int peakElement(int[] A) {
    int N = A.length;
    if (N == 1) return A[0];
    if (A[0]     >= A[1])     return A[0];
    if (A[N - 1] >= A[N - 2]) return A[N - 1];

    int low = 1, high = N - 2;
    while (low <= high) {
        int mid = low + ((high - low) / 2);
        if (A[mid] > A[mid + 1] && A[mid] > A[mid - 1]) return A[mid];
        else if (A[mid] > A[mid - 1]) low  = mid + 1;
        else                          high = mid - 1;
    }
    return -1;
}

public int searhAMatrix(int[][] A, int B) {
    int N = A.length, M = A[0].length;
    int low = 0, high = (N * M) - 1;

    while (low <= high) {
        int mid = low + ((high - low) / 2);
        int r = mid / M, c = mid % M;
        if (A[r][c] == B)      return 1;
        else if (A[r][c] < B)  low  = mid + 1;
        else                   high = mid - 1;
    }
    return 0;
}

public int minimumCostToBuildAnArray(int A, int B, int[][] C) {
    int ans = 1_000_000_000, lb;
    for (int i = 0; i < A; i++) Arrays.sort(C[i]);

    for (int i = 0; i < A - 1; i++) {
        for (int j = 0; j < B; j++) {
            lb = lower_bound(C[i + 1], C[i][j]);
            if (lb != B) ans = Math.min(ans, Math.abs(C[i][j] - C[i + 1][lb]));
            if (lb != 0) ans = Math.min(ans, Math.abs(C[i][j] - C[i + 1][lb - 1]));
        }
    }
    return ans;
}

private int lower_bound(int[] a, int val) {
    int low = 0, high = a.length - 1, ans = a.length;
    while (low <= high) {
        int mid = (high - low) / 2 + low;
        if (a[mid] < val) low = mid + 1;
        else { ans = mid; high = mid - 1; }
    }
    return ans;
}

public int maximumHeightOfAStaircase(int A) {
    int x = 1, steps = 0;
    while (A >= x) {
        steps++;
        A -= x;
        x++;
    }
    return steps;
}

public int staircaseBS(int A) {
    long low = 0, high = (long) Math.sqrt(2.0 * A) + 1, ans = 0;
    while (low <= high) {
        long mid = low + (high - low) / 2;
        if (mid * (mid + 1) / 2 <= A) { ans = mid; low = mid + 1; }
        else high = mid - 1;
    }
    return (int) ans;
}

