}

public int squareRootOfANumber(int A) {
    if (A == 0) return 0;
    long low = 1, high = A / 2, sqrt = 1;

    while (low <= high) {
        long mid = low + ((high - low) / 2);
        long numPos = mid * mid;
        if (numPos <= A) { sqrt = mid; low = mid + 1; }
        else             high = mid - 1;
    }
    return (int) sqrt;
}

