public int rotatedSortedArraySearch(int[] A, int B) {
    int N = A.length;
    int low = 0, high = N - 1;
    int k = rotationFactor(A);

    if (B == A[0]) return 0;
    else if (B > A[0]) high = k > 0 ? k - 1 : N - 1;
    else               low  = k;

    while (low <= high) {
        int mid = low + ((high - low) / 2);
        if (B < A[mid])      high = mid - 1;
        else if (B > A[mid]) low  = mid + 1;
        else                 return mid;
    }
    return -1;
}

private int rotationFactor(int[] A) {
    int N = A.length, low = 0, high = N - 1, rotation = 0;
    while (low <= high) {
        int mid = low + ((high - low) / 2);
        if (A[mid] >= A[0]) low = mid + 1;
        else { rotation = mid; high = mid - 1; }
    }
    return rotation;
}

public int mergeAndPick(int[] A, int[] B) {
    int m = A.length, n = B.length;
    int[] merged = new int[m + n];
    int i = 0, j = 0, k = 0;
    while (i < m && j < n) merged[k++] = A[i] <= B[j] ? A[i++] : B[j++];
    while (i < m) merged[k++] = A[i++];
    while (j < n) merged[k++] = B[j++];
    int t = m + n;
    return t % 2 == 1 ? merged[t/2] : (merged[t/2 - 1] + merged[t/2]) / 2;
}

public int findMedianInSortedArrays(int[] A, int[] B) {
    if (A.length > B.length) return findMedianInSortedArrays(B, A);

    int n = A.length, m = B.length;
    int low = 0, high = n;
    int leftCount = (n + m + 1) / 2;

    while (low <= high) {
        int pX = (low + high) / 2;
        int pY = leftCount - pX;

        int maxLeftX  = pX == 0 ? Integer.MIN_VALUE : A[pX - 1];
        int minRightX = pX == n ? Integer.MAX_VALUE : A[pX];
        int maxLeftY  = pY == 0 ? Integer.MIN_VALUE : B[pY - 1];
        int minRightY = pY == m ? Integer.MAX_VALUE : B[pY];

        if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
            if ((n + m) % 2 == 0)
                return (Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY)) / 2;
            return Math.max(maxLeftX, maxLeftY);
        } else if (maxLeftX > minRightY) high = pX - 1;
        else                              low  = pX + 1;
    }
    return 0;
}

public int flattenSort(int[][] A) {
    int n = A.length, m = A[0].length;
    int[] flat = new int[n * m];
    int k = 0;
    for (int[] row : A) for (int v : row) flat[k++] = v;
    Arrays.sort(flat);
    return flat[(n * m) / 2];
}

public int findMatrixMedian(int[][] A) {
    int n = A.length, m = A[0].length;
    int low = 0, high = 1_000_000_000;
    int medPos = n * m / 2, ans = -1;

    while (low <= high) {
        int mid = (high - low) / 2 + low;
        int cnt = 0;
        for (int i = 0; i < n; i++) cnt += lowerBound(A[i], mid);
        if (cnt > medPos) high = mid - 1;
        else { ans = mid; low = mid + 1; }
    }
    return ans;
}

private int lowerBound(int[] A, int val) {
    int l = 0, h = A.length - 1, ans = -1;
    while (l <= h) {
        int mid = (h - l) / 2 + l;
        if (A[mid] < val) { ans = mid; l = mid + 1; }
        else h = mid - 1;
    }
    return ans + 1;
}

public int[] addOrNot(int[] A, int B) {
    Arrays.sort(A);
    int n = A.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + A[i];

    int[] ans = new int[]{ -1, -1 };
    for (int i = 0; i < n; i++) {
        int lo = 1, hi = i + 1, mx = 0;
        while (lo <= hi) {
            int cnt = (lo + hi) / 2;
            if ((long) A[i] * cnt - (prefix[i + 1] - prefix[i - cnt + 1]) <= B) {
                mx = cnt;
                lo = cnt + 1;
            } else hi = cnt - 1;
        }
        if (ans[0] < mx) { ans[0] = mx; ans[1] = A[i]; }
    }
    return ans;
}

public int athMagicalNumber(int A, int B, int C) {
    long lcm = (long) B * C / gcd(B, C);
    long low = 2, high = (long) A * Math.min(B, C), ans = 0;
    while (low <= high) {
        long mid = (high - low) / 2 + low;
        long cntB = mid / B, cntC = mid / C, cntBC = mid / lcm;
        if (cntB + cntC - cntBC >= A) { ans = mid; high = mid - 1; }
        else                            low = mid + 1;
    }
    return (int) (ans % 1_000_000_007L);
}

private int gcd(int x, int y) { return x == 0 ? y : gcd(y % x, x); }

public int BthSmallestTripletSum(int[] A, int B) {
    Arrays.sort(A);
    int n = A.length;
    int low = 0, high = A[n-1] + A[n-2] + A[n-3], ans = 0;
    while (low <= high) {
        int mid = (high - low) / 2 + low;
        int count = countLess(A, mid);
        if (count >= B) high = mid - 1;
        else { ans = mid; low = mid + 1; }
    }
    return ans;
}

private int countLess(int[] A, int val) {
    int cnt = 0;
    for (int i = 0; i < A.length; i++) {
        int s = i + 1, e = A.length - 1;
        while (s < e) {
            if (A[i] + A[s] + A[e] < val) { cnt += e - s; s++; }
            else e--;
        }
    }
    return cnt;
}

public int paintersPartitionMinimumTimeToPaint(int A, int B, int[] C) {
    int MOD = 10000003;
    if (C.length == 0) return 0;
    if (A > C.length) A = C.length;

    int maxBoard = 0;
    long totalSum = 0;
    for (int b : C) { maxBoard = Math.max(maxBoard, b); totalSum += b; }

    long left = maxBoard, right = totalSum, result = right;
    while (left <= right) {
        long mid = (left + right) / 2;
        if (isPaintingCompletionPossible(C, A, mid)) { result = mid; right = mid - 1; }
        else                                          left  = mid + 1;
    }
    return (int) ((result * B) % MOD);
}

private boolean isPaintingCompletionPossible(int[] C, int A, long maxTime) {
    int painters = 1;
    long currentSum = 0;
    for (int b : C) {
        if (currentSum + b > maxTime) {
            painters++;
            currentSum = b;
            if (painters > A) return false;
        } else currentSum += b;
    }
    return true;
}

public int aggressiveCowsLargestMinDistance(int[] A, int B) {
    Arrays.sort(A);
    int left = 1, right = A[A.length - 1] - A[0], result = 0;

    while (left <= right) {
        int mid = (left + right) / 2;
        if (canPlaceCows(A, B, mid)) { result = mid; left = mid + 1; }
        else                          right = mid - 1;
    }
    return result;
}

private boolean canPlaceCows(int[] stalls, int B, int minDist) {
    int count = 1, lastPlaced = stalls[0];
    for (int i = 1; i < stalls.length; i++) {
        if (stalls[i] - lastPlaced >= minDist) {
            count++;
            lastPlaced = stalls[i];
            if (count == B) return true;
        }
    }
    return false;
}

public int minimumDifferenceBetweenBooksAllotted(int[] books, int students) {
    if (books == null || books.length == 0) return -1;
    if (students <= 0 || students > books.length) return -1;

    int maxPage = 0, maxSingleBook = 0;
    for (int x : books) { maxPage += x; maxSingleBook = Math.max(x, maxSingleBook); }

    int low = Math.max(1, maxSingleBook), high = maxPage, ans = high;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (canBeAllotted(books, students, mid)) { ans = mid; high = mid - 1; }
        else                                       low  = mid + 1;
    }
    return ans;
}

private boolean canBeAllotted(int[] books, int students, int maxPages) {
    int allotted = 1, current = 0;
    for (int p : books) {
        current += p;
        if (current > maxPages) { allotted++; current = p; }
        if (allotted > students) return false;
    }
    return true;
}

public int maxSubArrayFactorLessThanB(int[] nums, int sum) {
    int low = 0, high = nums.length, K = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (subArrayOk(nums, sum, mid)) { K = mid; low = mid + 1; }
        else                              high = mid - 1;
    }
    return K;
}

private boolean subArrayOk(int[] nums, int sum, int K) {
    if (K == 0) return true;
    long windowSum = 0;
    for (int i = 0; i < K; i++) windowSum += nums[i];
    if (windowSum > sum) return false;

    for (int i = K; i < nums.length; i++) {
        windowSum += nums[i] - nums[i - K];
        if (windowSum > sum) return false;
    }
    return true;
}
